<script setup>
import {ref,onMounted} from 'vue'
import {api} from '../lib/api'
import {useArcade} from '../stores/arcade'
import CharacterPicker from '../components/CharacterPicker.vue'
const s=useArcade(),data=ref(null),error=ref(''),busy=ref(false),pending=ref(null),dialog=ref(null),message=ref('');let key=''
async function load(){data.value=await api('/collection');await s.refresh()}
function choose(form){pending.value=form;key=crypto.randomUUID();dialog.value.showModal()}
async function confirm(){if(busy.value)return;busy.value=true;error.value='';try{const result=await api('/collection',{method:'POST',body:{target:pending.value.id,requestKey:key}});message.value=result.purchased?'도감에 영구 등록했어요. 다음부터 무료로 선택할 수 있어요.':'파트너를 변경했어요.';dialog.value.close();await load()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>load().catch(e=>error.value=e.message))
</script>
<template><section class="collection-page"><header><div><p>MY POKÉDEX</p><h1>포켓몬 도감</h1><p>한 번 만난 파트너는 무료로 다시 선택해요.</p></div><RouterLink to="/pet" class="button light">파트너 돌보기</RouterLink></header><p v-if="message" class="notice" role="status">{{message}}</p><p v-if="error&&!dialog?.open" class="notice" role="alert">{{error}}</p><section v-if="data" class="panel"><h2>함께한 파트너 {{data.characters.filter(c=>c.owned).length}} / {{data.characters.length}}</h2><p>최종 강화 완료한 계열은 완료 상태를 보존합니다. 미완료 계열은 변경 시 1단계로 돌아가며 강화 확률·실패 시 디그다 규칙을 유지해요.</p><CharacterPicker :model-value="s.partner.id" :locked="s.data.partnerLocked" @changed="load"/><details class="collection-status"><summary><span class="collection-counts"><b>보유 {{data.characters.filter(c=>c.owned).length}} / {{data.characters.length}}</b><span>강화 완료 {{data.characters.filter(c=>c.completed).length}}</span><span>미보유 {{data.characters.filter(c=>!c.owned).length}}</span></span><span class="collection-expand">보유 목록 보기 ⌄</span></summary><ul><li v-for="c in data.characters" :key="c.id"><strong>{{c.name}}</strong><span :class="{completed:c.completed,locked:!c.owned}">{{c.completed?'★ 강화 완료':c.owned?'✓ 보유':'🔒 미보유'}}</span></li></ul></details></section><section v-if="data" class="panel"><h2>디그다 특별 도감</h2><p>디그다 3단계 강화를 완료한 상태에서 기본 디그다를 5,000P로 등록할 수 있어요. 이후 다른 모습은 각각 1,000P로 등록하고 무료로 선택해요. 강화 실패로 변한 디그다는 먼저 복구해야 합니다.</p><div class="diglett-collection"><article v-for="form in data.diglett" :key="form.id"><img :src="form.image" :alt="form.name"/><h3>{{form.name}}</h3><span>{{form.stage}}단계 · {{form.owned?'영구 보유':form.price.toLocaleString()+'P'}}</span><button :disabled="busy||(!form.owned&&(form.stage===1?!data.canRegisterDiglett:!data.diglett[0].owned))" @click="choose(form)">{{form.owned?'선택':'도감 등록'}}</button></article></div></section><dialog ref="dialog" aria-label="디그다 도감 확인"><h2>{{pending?.name}}</h2><p>{{pending?.owned?'이 모습으로 선택할까요?':pending?.price.toLocaleString()+'P를 사용해 도감에 영구 등록할까요?'}}</p><p v-if="error" role="alert">{{error}}</p><div class="toolbar"><button class="light" :disabled="busy" @click="dialog.close()">취소</button><button :disabled="busy" @click="confirm">{{busy?'처리 중…':'확인'}}</button></div></dialog></section></template>
<style scoped>.collection-page{max-width:1400px;margin:auto;min-width:0}.collection-page>header{display:flex;align-items:center;justify-content:space-between;gap:15px}.collection-page .panel{margin:20px 0}.collection-page p{line-height:1.9}.collection-status{margin-top:18px;border-top:1px solid var(--rpg-mid);padding-top:14px}.collection-status summary{cursor:pointer;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;list-style:none;padding:8px 0}.collection-status summary::-webkit-details-marker{display:none}.collection-counts{display:flex;align-items:center;gap:12px;flex-wrap:wrap;font-size:12px}.collection-counts>b{color:var(--rpg-ink)}.collection-expand{font-size:11px;color:var(--rpg-ink)}.collection-status ul{list-style:none;margin:12px 0 0;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:8px}.collection-status li{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:11px 12px;background:var(--rpg-soft);border:1px solid var(--rpg-mid);border-radius:4px;font-size:12px;min-width:0}.collection-status li strong{overflow-wrap:anywhere}.collection-status li span{font-size:10px;white-space:nowrap}.collection-status .locked{opacity:.65}.collection-status .completed{font-weight:bold;color:var(--rpg-ink)}.diglett-collection{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:15px}.diglett-collection article{padding:15px;border:2px solid var(--rpg-mid);display:flex;flex-direction:column;gap:12px;text-align:center}.diglett-collection img{height:110px;width:100%;object-fit:contain}.diglett-collection h3{font-size:14px;margin:0}.diglett-collection span{font-size:11px}.collection-page dialog{max-width:min(460px,85vw)}@media(max-width:600px){.diglett-collection{grid-template-columns:repeat(2,minmax(0,1fr))}.collection-page>header{flex-wrap:wrap}}</style>
